# Verify the rule for demo
width = len(demo_in[0])
height = len(demo_in)

def check_full_line(grid, axis='row'):
    """Check if row/col is a full line of the minority color"""
    if axis == 'row':
        for r in range(height):
            color = grid[r][0]
            if all(grid[r][c] == color for c in range(width)):
                yield r
    else:
        for c in range(width):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(height)):
                yield c

full_rows = list(check_full_line(demo_in))
full_cols = list(check_full_line(demo_in))

print("Full rows in demo:", full_rows)
print("Full cols in demo:", full_cols)

# Apply the rule
def apply_rule(grid, is_demo=False):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    # Identify minority color
    counts = Counter(c for row in grid for c in row)
    min_color = min(counts.keys(), key=lambda x: counts[x])

    # Check each row if it's full of minority color
    full_row_indices = []
    for r in range(len(result)):
        color = grid[r][0]
        if color == min_color and all(grid[r][c] == min_color for c in range(len(grid[0]))):
            full_row_indices.append(r)

    # Check each col if it's full of minority color  
    full_col_indices = []
    for c in range(len(grid[0])):
        color = grid[0][c]
        if color == min_color and all(grid[r][c] == min_color for r in range(len(grid))):
            full_col_indices.append(c)

    # A cell becomes 2 if it's in a full row OR full col of the minority color
    for r in range(len(result)):
        for c in range(len(result[0])):
            if result[r][c] == min_color:
                if r in full_row_indices or c in full_col_indices:
                    result[r][c] = 2

    return result

